package br.com.sistemacardapio.autenticacao;
import java.util.List;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/admin/empresas/{empresaId}/usuarios")@PreAuthorize("hasRole('SUPER_ADMIN')")public class UsuarioSuperAdminController{private final UsuarioAdminService service;public UsuarioSuperAdminController(UsuarioAdminService service){this.service=service;}@GetMapping public List<UsuarioAdminService.Response>listar(@PathVariable UUID empresaId){return service.listar(empresaId);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public UsuarioAdminService.Response criar(@PathVariable UUID empresaId,@RequestBody UsuarioAdminService.Request request){return service.criar(empresaId,request);}@PutMapping("/{id}")public UsuarioAdminService.Response atualizar(@PathVariable UUID empresaId,@PathVariable UUID id,@RequestBody UsuarioAdminService.UpdateRequest request){return service.atualizar(empresaId,id,request);}@PutMapping("/{id}/senha")public UsuarioAdminService.Response senha(@PathVariable UUID empresaId,@PathVariable UUID id,@RequestBody UsuarioAdminService.PasswordRequest request){return service.redefinir(empresaId,id,request);}}
